from collections import deque

def get_0_components(inp):
    visited = set()
    components = []
    for r in range(rows):
        for c in range(cols):
            if inp[r][c] == 0 and (r,c) not in visited:
                comp = set()
                queue = deque([(r,c)])
                visited.add((r,c))
                comp.add((r,c))
                while queue:
                    cr, cc = queue.popleft()
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols and inp[nr][nc] == 0 and (nr,nc) not in visited:
                            visited.add((nr,nc))
                            comp.add((nr,nc))
                            queue.append((nr,nc))
                components.append(comp)
    return components

