                if comp and comp[1]:  # has barrier
                    out[i][j] = 2
            elif inp[i][j] == 7:
                # Check if adjacent to any 0 that becomes 2
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    ni, nj = i+dr, j+dc
                    if 0 <= ni < rows and 0 <= nj < cols:
