                                out[i][j] = 2
                                break
    return out

def is_barrier_connected(inp, r, c):
    if inp[r][c] == 0:
        return get_0_component_with_marker(inp, r, c, barrier_rows)[1]
    return False

def get_0_component_with_marker(inp, start_r, start_c, barrier_rows):
    visited = set()
    has_barrier = False
    queue = deque([(start_r, start_c)])
    visited.add((start_r, start_c))

    if start_r in barrier_rows:
        has_barrier = True

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols and inp[nr][nc] == 0 and (nr,nc) not in visited:
                visited.add((nr,nc))
                queue.append((nr,nc))
                if nr in barrier_rows:
                    has_barrier = True
    return visited, has_barrier

